        {"선택 버전과 버전 정보가 다릅니다.",new[]{"Selected version does not match its manifest.","選択版とバージョン情報が一致しません。"}},
        {"패키지 용량이 릴리스 정보와 다르거나 제한을 초과했습니다.",new[]{"Package size differs from the release or exceeds the limit.","サイズがリリース情報と異なるか、上限を超えています。"}},
        {" 다운로드 중…",new[]{" downloading…"," ダウンロード中…"}},
        {"다른 내용의 파일이 이미 있습니다. 새 폴더를 선택하세요: ",new[]{"A different file already exists. Choose another folder: ","内容が異なるファイルがあります。別のフォルダーを選択してください: "}},
        {"저장소 형식을 확인하세요.",new[]{"Check the repository format.","リポジトリの形式を確認してください。"}},
        {"런처 자산 주소가 저장소와 다릅니다.",new[]{"Launcher asset belongs to another repository.","ランチャーの場所がリポジトリと異なります。"}},
        {"런처 파일 또는 크기 정보가 맞지 않습니다.",new[]{"Launcher file or size information does not match.","ランチャーのファイルまたはサイズ情報が一致しません。"}},
        {"런처 다운로드 주소가 저장소와 다릅니다.",new[]{"Launcher download belongs to another repository.","ランチャーの取得先がリポジトリと異なります。"}},
        {"런처 파일 이름을 Macross30Launcher.exe로 유지하세요.",new[]{"Keep the launcher named Macross30Launcher.exe.","ランチャー名はMacross30Launcher.exeのままにしてください。"}},
        {"런처 ",new[]{"Launcher ","ランチャー "}},
